if abs(pos.x)>1e-4 or abs(pos.y)>1e-4: raise RuntimeError(f'QA torre nao zerou XY: {tuple(pos)}')
post={'tower_hall':dxy(tower,hall),'tower_passadico':dxy(tower,passadico),'hall_passadico':dxy(hall,passadico)}
for k in pre:
